add_filter( 'woocommerce_get_price_html', 'perfectpixel_free_instead_of_zero', 20, 2 );

function perfectpixel_free_instead_of_zero( $html, $product ) {
	if ( ! $product || $product->is_type( array( 'variable', 'grouped' ) ) || '' === $product->get_price() || 0.0 !== (float) $product->get_price() ) {
		return $html;
	}
	$free = '<span class="amount perfectpixel-free">' . esc_html( '{{free_price_label}}' ) . '</span>';
	if ( $product->is_on_sale() && (float) $product->get_regular_price() > 0 ) {
		return '<del aria-hidden="true">' . wc_price( wc_get_price_to_display( $product, array( 'price' => $product->get_regular_price() ) ) ) . '</del> <ins>' . $free . '</ins>';
	}
	return $free;
}
